   465|              subject: 'New Consulting Intake: ' + (payload.company_name || 'Unknown Company'),
   466|              content_type: 'text/plain',
   467|              body: body
   468|            })
   469|          });
   470|
   471|          if (!resp.ok) throw new Error('HTTP ' + resp.status);
   472|
