   478|          iframe.style.display = 'none';
   479|          iframe.name = 'hidden-form-submit';
   480|          document.body.appendChild(iframe);
   481|
   482|          // Reset form but keep hidden
   483|          form.target = 'hidden-form-submit';
   484|          form.submit();
   485|        } catch (err) {
